import React, { useEffect, useState } from 'react';
import {
     Button, Modal, ModalHeader, ModalBody, 
     ModalFooter, FormGroup, Label, Input 
} from 'reactstrap';

const UserList = () => {

    const [users, setUsers] = useState([]);
    const [modalOpen, setModalOpen] = useState(false);
    const [userEdit, setUserEdit] = useState(null);

    useEffect(() => {
        fetchUsers();
    }, []);

    const fetchUsers = () => {
        fetch('http://localhost/multimedios/Proyecto-grupal/API/users.php')
            .then(response => response.json())
            .then((dataResponse) => {
                setUsers(dataResponse.data);
            })
            .catch(error => {
                console.error('Error al cargar:', error);
                setUsers([]); // Asegúrate de que users siempre sea un arreglo
            });
    };

    const toggleEditModal = (user) => {
        setUserEdit(user);
        setModalOpen(!modalOpen);
    }

    const handleChange = (e) => {
        const { id, value } = e.target;
        setUserEdit(prevState => ({
            ...prevState,
            [id]: value
        }));
    }

    const saveUser = async () => {
        // Aquí deberías manejar la lógica para guardar el usuario
    }

    return ( 
        <div className='container'>
            <br /><br /><br />
            <Button color='dark' onClick={() => toggleEditModal({})}> 
                Agregar Usuario
            </Button>

            <table className="table table-info">
                <thead>
                    <tr>
                        <th scope="col">Acciones</th>
                        <th scope="col">Id</th>
                        <th scope="col">Nombre</th>
                        <th scope="col">Email</th>
                        <th scope="col">Password</th>
                        <th scope="col">Fecha de Registro</th>
                    </tr>
                </thead>
                <tbody>
                    {
                        users && users.length > 0 ? (
                            users.map(user => (
                                <tr key={user.idUser}>
                                    <td>
                                        <Button color="primary" onClick={() => toggleEditModal(user)}>Editar</Button>
                                    </td>
                                    <td>{user.idUser}</td>
                                    <td>{user.name}</td>
                                    <td>{user.email}</td>
                                    <td>{user.password}</td>
                                    <td>{user.releaseDate}</td>
                                </tr>
                            ))
                        ) : (
                            <tr>
                                <td colSpan="6">No se encontraron usuarios</td>
                            </tr>
                        )
                    }
                </tbody>
            </table>

            <Modal isOpen={modalOpen}>
                <ModalHeader>Modal Usuario</ModalHeader> 
                <ModalBody>
                    <Label for="name">Nombre</Label>
                    <Input type="text" id="name" value={userEdit?.name || ''} onChange={handleChange} />
                    <Label for="email">Email</Label>
                    <Input type="email" id="email" value={userEdit?.email || ''} onChange={handleChange} />
                    <Label for="password">Password</Label>
                    <Input type="password" id="password" value={userEdit?.password || ''} onChange={handleChange} />
                    <Label for="releaseDate">Fecha de Registro</Label>
                    <Input type="date" id="releaseDate" value={userEdit?.releaseDate || ''} onChange={handleChange} />                                                                                
                </ModalBody>   
                <ModalFooter>
                    <Button color='primary' onClick={saveUser}>Guardar</Button>
                    <Button color='secondary' onClick={() => toggleEditModal(null)}>Cerrar</Button>
                </ModalFooter>
            </Modal>    
        </div>
    );
}

export default UserList;
